            updateTask.run(form.get('completed') === '1' ? 1 : 0, taskId, projectId);
          }
        }
        redirectToProject(response, projectId, filter, selectedPriority);
        return;
      }
    }
    sendHtml(response, 404, page('Not found', '<h1>Not found</h1>'));
  } catch (error) {
