    assert.match(active, /Complete Renamed task" checked/);
    assert.deepEqual([...active.matchAll(/id="task-(\d+)" type="checkbox"/g)].map(match => Number(match[1])), [1, 2, 3, 5]);
    assert.match(await get('/'), /2\/4 completed/);
