    await post('/projects/1/restore');
    assert.equal(await get('/projects/1'), active);
    assert.doesNotMatch(select(await get('/projects/1'), 'default-task-priority'), /disabled/);
    await post('/projects/1/tasks', { title: 'After restart' });
